    text: "import ChangesetWebform from 'react-changeset-webforms/src/components/ChangesetWebform.jsx';\n\nconst formSchema = {\n  formSettings: {\n    formName: 'Signup',\n    submitButtonText: 'Sign up',\n    clearFormAfterSubmit: true,\n    resetFormButton: true,\n    clearFormButton: true,\n  },\n  fields: [\n    {\n      fieldId: 'name',\n      fieldLabel: 'Name',\n      fieldType: 'input',\n      showValidationWhenFocussed: true,\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: true,\n        },\n      ],\n      inputType: 'text',\n    },\n    {\n      fieldId: 'email',\n      fieldLabel: 'Email',\n      fieldType: 'input',\n      validatesOn: ['$inherited', 'insertWithValue'],\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: true,\n        },\n        {\n          validationMethod: 'validateFormat',\n          arguments: { type: 'email' },\n        },\n      ],\n      inputType: 'email',\n    },\n    {\n      fieldId: 'recoveryEmail',\n      fieldLabel: 'Recovery email',\n      fieldType: 'input',\n      validatesOn: ['$inherited', 'insertWithValue'],\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: true,\n        },\n        {\n          validationMethod: 'validateFormat',\n          arguments: { type: 'email' },\n        },\n      ],\n      inputType: 'email',\n    },\n    {\n      fieldId: 'password',\n      fieldLabel: 'Password (Minimum 8 characters)',\n      fieldType: 'input',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: true,\n        },\n        {\n          validationMethod: 'validateLength',\n          arguments: { min: 8, max: 72 },\n        },\n      ],\n      inputType: 'password',\n    },\n    {\n      fieldId: 'country',\n      fieldLabel: 'Country',\n      fieldType: 'powerSelect',\n      placeholder: 'Select',\n      searchEnabled: true,\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: { presence: true, description: 'Nation of origin' },\n        },\n      ],\n      options: ['Afghanistan', 'Åland Islands', 'Albania', 'Algeria', 'American Samoa', 'Andorra', 'Angola', 'Anguilla', 'Antarctica', 'Antigua and Barbuda', 'United States'],\n    },\n    {\n      fieldId: 'birthDate',\n      fieldLabel: 'Date of Birth',\n      fieldType: 'powerDatePicker',\n      showTimeSelector: true,\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: { presence: true, description: 'Date of birth' },\n        },\n      ],\n    },\n    {\n      fieldId: 'acceptTerms',\n      fieldType: 'radioButtonGroup',\n      fieldLabel: 'Do you agree to the terms and conditions?',\n      validationRules: [\n        {\n          validationMethod: 'validateInclusion',\n          arguments: {\n            list: ['true'],\n            message: 'You must accept the terms to continue.',\n          },\n        },\n      ],\n      options: [\n        {\n          label: 'I agree',\n          value: 'true',\n        },\n        {\n          label: 'I do not agree',\n          value: 'false',\n        },\n      ],\n    },\n    {\n      fieldId: 'confirmHuman',\n      fieldType: 'singleCheckbox',\n      fieldLabel: 'Are you a human?',\n      checkBoxLabel: 'Are you human',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n            message: 'Please confirm that you are not a robot.',\n          },\n        },\n      ],\n    },\n    {\n      fieldId: 'cookieConsent',\n      fieldType: 'checkboxGroup',\n      fieldLabel: 'Please select the cookies you consent to',\n      validationRules: [\n        {\n          validationMethod: 'validateLength',\n          arguments: {\n            min: 2,\n            allowNone: false,\n            message: 'You must select at least two cookie consent options.',\n          },\n        },\n      ],\n      options: [\n        {\n          label: 'Essential',\n          key: 'essential',\n        },\n        {\n          label: 'Analytics',\n          key: 'analytics',\n        },\n        {\n          label: 'Marketing',\n          key: 'marketing',\n        },\n      ],\n    },\n  ],\n};\n\nfunction submit() {\n  return new Promise((resolve) => {\n    setTimeout(() => {\n      resolve();\n    }, 500);\n  });\n}\n\nexport default function SignupForm() {\n  return (\n    <ChangesetWebform\n      formSchema={formSchema}\n      submitData={submit}\n    />\n  );\n}",
