    text: "import ChangesetWebform from 'react-changeset-webforms/src/components/ChangesetWebform.jsx';\n\nconst formSchema = {\n  formSettings: {\n    formName: 'validationBasics',\n    hideSubmitButton: true,\n  },\n  fields: [\n    {\n      fieldId: 'name',\n      fieldType: 'input',\n      fieldLabel: 'Name',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n        {\n          validationMethod: 'validateLength',\n          arguments: {\n            presence: true,\n          },\n        },\n      ],\n    },\n    {\n      fieldId: 'email',\n      fieldType: 'input',\n      inputType: 'email',\n      fieldLabel: 'Email',\n      validatesOn: ['$inherited', 'insertWithValue'],\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n          validationMethod: 'validateFormat',\n          arguments: {\n            type: 'email',\n          },\n        },\n      ],\n    },\n  ],\n};\n\nexport default function ValidationBasics() {\n  return <ChangesetWebform formSchema={formSchema} />;\n}",
